Boolean dstcrypt_delete_isk (void)        
{       
  if(dstcrypt_vars.nvfs_entry_done)
  {
    memset(&dstcrypt_nvfs_entry , NULL , sizeof(DstCrypt_Nvfs_Entry)) ;

    #if DBG_DSTCRYPT == 1
      dstcrypt_dbg_print("\nDstCrypt Isk Delete" , NULL , NULL) ;
    #endif    
    TRACE("\rDstCrypt Isk Delete\r");
    return (nvfs_delete(nvfs_dst_isk) == NVFS_OK );
  }

  return FALSE ;
}
